   731           */
   732          len = sizeof(enc_oid);
   733          result =
   734              asn1_read_value(pkcs8_asn, "encryptionAlgorithm.algorithm",
   735                              enc_oid, &len);
   736          if (result != ASN1_SUCCESS) {
   737                  gnutls_assert();
   738                  goto error;
   739          }
