   751              asn1_der_decoding_startEnd(pkcs8_asn, raw_key->data,
   752                                         raw_key->size,
   753                                         "encryptionAlgorithm.parameters",
   754                                         &params_start, &params_end);
   755          if (result != ASN1_SUCCESS) {
   756                  gnutls_assert();
