   758                  goto error;
   759          }
   760          params_len = params_end - params_start + 1;
   761
   762          result =
   763              _gnutls_read_pkcs_schema_params(&schema, password,
   764                                      &raw_key->data[params_start],
   765                                      params_len, &kdf_params, &enc_params);
